import React, { useState } from "react";
import axios from "axios";

const api = axios.create({
  baseURL: "http://localhost:8000",
});

api.interceptors.request.use((config) => {
  const token = localStorage.getItem("token");
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

function OcrPage({ onLogout }) {
  const [selectedFile, setSelectedFile] = useState(null);
  const [ocrResult, setOcrResult] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");

  const handleFileChange = (event) => {
    setSelectedFile(event.target.files[0]);
    setOcrResult("");
    setError("");
  };

  const handleUpload = async () => {
    if (!selectedFile) {
      setError("Please select a file first.");
      return;
    }

    const formData = new FormData();
    formData.append("file", selectedFile);

    setIsLoading(true);
    setError("");

    try {
      const response = await api.post("/ocr", formData, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      });
      setOcrResult(response.data.text);
    } catch (err) {
      setError(err.response?.data?.detail || "An error occurred during OCR processing.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="ocr-container">
      <div className="ocr-header">
        <h2>Extract Text from Bills & Receipts</h2>
        <button className="btn btn-danger" onClick={onLogout}>Logout</button>
      </div>
      <p className="ocr-subheading">Upload an image of a bill or receipt to extract the text.</p>

      <div className="upload-section">
        <input 
          type="file" 
          onChange={handleFileChange} 
          accept="image/*" 
          className="file-input"
        />
        <button 
          className="btn btn-primary" 
          onClick={handleUpload} 
          disabled={isLoading || !selectedFile}
        >
          {isLoading ? "Extracting..." : "Extract Text"}
        </button>
      </div>

      {error && <div className="error-message">{error}</div>}

      {ocrResult && (
        <div className="result-section">
          <h3>Extracted Text:</h3>
          <pre className="ocr-result-text">{ocrResult}</pre>
        </div>
      )}
    </div>
  );
}

export default OcrPage;
